        error;
    } else {
       const tagKeyName = Object.keys($$$).find(key => key === 'tag1');
         if (tagKeyName === undefined) {
             error;
         }
    };
} catch (e) {
    $$$ = original;
    put($$$);
}

function Login() {
    const result = JSON.parse(source.getLoginInfo());
    var username = result['账号'];
    var password = result['密码'];
    var options = {
	   body: `username=${username}&password=${password}&submit_login=1`,
	   method: 'POST'
	};
	if(Get('url') === 'https://jmcomicgo.me') {
		Log('请先获取URL');
		} else if(Get('url')) {
		Log("\n⏳正在登录中，请等一会，很快就好...");
		var request = JSON.parse(java.log(java.ajax(Get('url') +`/login,${JSON.stringify(options)}`)))
		if(request.status == '1') {
			Log('✅ 登录成功')
		} else {
			Log('❎ 登录失败')
			}
	} else {
		Log('❌ 未获取到有效URL，请切换url');
		}
	}

function typeP(e) {
    if (e == undefined) {
        e = 0;
    }
    return sortCriteria[e].label;
}

function tag(e) {
    if (tag == undefined) {
        tag = result.tag;
    }
    if (e == $$$.tag) {
        return Log('【标签切换提示】' + n(2) + '已经选择此标签，无需更换');
    }
    Log('【标签切换提示】' + n(2) + '已经切换到[' + typeP(e) + ']');
    $$$.tag = e;
    return put($$$);
}

function url() {
    var html = java.ajax(`https://jmcomicgo.me`)
    var url = html.match(/china"><span>(.*?)<\/span/)[1].replace(/\s+/g, "");
    var url1 = html.match(/first_line"><span>(.*?)<\/span/)[1].replace(/\s+/g, "");
    var url2 = html.match(/second_line"><span>(.*?)<\/span/)[1].replace(/\s+/g, "");
    if (url == $$$.url) {
         return Log('【站点提示】' + n(2) + '站点无需更换');
    }
    Log('站点变更:' + url)
    $$$.url = url;
    $$$.urls[0] = url
    $$$.urls[1] = url1;
    $$$.urls[2] = url2;
    return put($$$);
	}

function qh(){
	if ($$$.url = $$$.urls[0]) {
		$$$.urls[0] = $$$.urls[1];
		$$$.urls[1] = $$$.urls[2];
		$$$.urls[2] = $$$.url;
		$$$.url = $$$.urls[0];
		Log('站点变更:' + $$$.urls[0])
		return put($$$);
		} 
	}

function qh1() {
  $$$.shunt = ($$$.shunt + 1) % 4;
  Log("分流" + nums[$$$.shunt]);
  return put($$$);
}

function qh2() {
  $$$.tag1 = ($$$.tag1 + 1) % 6;
  Log('【分类切换提示】' + n(2) + '已经切换到[' + Category[$$$.tag1][0] + ']');
  return put($$$);
}

function Log(e) {
    if (e == undefined) {
        return;
    }
    java.longToast(e);
}

